// Reversible curation boundary. Add an ID/slug only after the client verifies the record.
// Bundled examples and unverified photographs remain on disk, never appended by default.
export const verifiedStaticContent = { works: [], news: [], galleryPhotos: [], galleryVideos: [], galleryPreview: [] };
export function approvedStatic(items, source) {
  const approved = verifiedStaticContent[source] || [];
  return items.filter(item => approved.includes(String(item.slug || item.id)));
}
// These exact entries are generated by the former admin demo-fill buttons.
export const knownDemoTitles = ["Demo Road Improvement Work", "Demo Ward Development Update"];
export const publicContentQuery = { published: true, titleEn: { $nin: knownDemoTitles } };
export function publicItems(items) {
  return items.filter(item => item.published !== false && !knownDemoTitles.includes(item.titleEn));
}
